'use strict';
const {phases,lessons,patterns,designs,refs}=window.COURSE;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='system-design-path:v1';
let saved={done:[]},noticeTimer,timerInterval=null,timerEnd=null,timerRemaining=45*60,timerDesign=null;
try{const value=JSON.parse(localStorage.getItem(key)||'null');if(value&&Array.isArray(value.done))saved.done=value.done.filter(x=>typeof x==='string');}catch{}
const validKeys=new Set([...lessons.map(x=>'lesson/'+x.id),...patterns.map(x=>'pattern/'+x.id),...designs.map(x=>'design/'+x.id)]);
saved.done=saved.done.filter(x=>validKeys.has(x));
const isDone=id=>saved.done.includes(id);
function notify(message){clearTimeout(noticeTimer);$('#notice').textContent=message;$('#notice').classList.add('visible');noticeTimer=setTimeout(()=>$('#notice').classList.remove('visible'),3500);}
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));return true;}catch{notify('Browser storage is unavailable. Progress will last only for this session.');return false;}}
function updateProgress(){const count=lessons.filter(x=>isDone('lesson/'+x.id)).length;$('#progress-label').textContent=`${count} of ${lessons.length} lessons complete`;$('#progress-bar').style.width=(100*count/lessons.length)+'%';}
function doneButton(type,id){const done=isDone(type+'/'+id);return `<button class="button ${done?'done':'secondary'}" data-complete="${type}/${id}" aria-pressed="${done}">${done?'✓ Completed':'Mark complete'}</button>`;}
function references(ids){return `<div class="references"><strong>Read the source · primary references for deeper study</strong>${[...new Set(ids)].map(id=>`<a href="${esc(refs[id][1])}" target="_blank" rel="noopener noreferrer">${esc(refs[id][0])} ↗</a>`).join('')}</div>`;}
function head(kicker,title,description){return `<p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1>${description?`<p class="lede">${esc(description)}</p>`:''}`;}
function section(id,title,body){return `<section id="${id}"><h2>${title}</h2><p>${esc(body)}</p></section>`;}
function toc(items,extra=''){return `<div class="toc"><strong>IN THIS GUIDE</strong>${items.map(([id,label])=>`<a href="#${id}" data-scroll="${id}">${label}</a>`).join('')}${extra}</div>`;}
function navPair(list,item,type){const i=list.indexOf(item);return `<div class="next-prev">${i>0?`<a href="#${type}/${list[i-1].id}">← ${esc(list[i-1].title)}</a>`:'<span></span>'}${i<list.length-1?`<a href="#${type}/${list[i+1].id}">${esc(list[i+1].title)} →</a>`:`<a href="#${type==='lesson'?'questions':type==='pattern'?'patterns':'questions'}">Back to ${type==='lesson'?'design questions':'catalog'} →</a>`}</div>`;}
function learn(){const next=lessons.find(l=>!isDone('lesson/'+l.id))||lessons[0];return head('A practical course · from foundations to interviews','Build systems you can explain.','Learn the fundamentals, recognize the patterns, then design under real constraints. Every lesson includes a worked example, a tradeoff, an exercise and references.')+
 `<div class="actions"><a class="button" href="#lesson/${next.id}">${saved.done.some(x=>x.startsWith('lesson/'))?'Continue learning':'Start with the fundamentals'} →</a><a class="button secondary" href="#questions">Explore design questions</a></div>
 <div class="stats">${[[phases.length,'ordered phases'],[lessons.length,'in-depth lessons'],[patterns.length,'design patterns'],[designs.length,'worked designs']].map(([n,label])=>`<div class="stat"><strong>${n}</strong><span>${label}</span></div>`).join('')}</div>
 <div class="callout"><strong>The study loop</strong><p>Predict an answer → read the theory → work the exercise → explain a tradeoff → change one constraint. Mark a lesson complete when you can explain it without looking.</p></div>
 <div class="section-heading"><h2>Your learning path</h2><span>Follow the phases in order. Revisit them as you design.</span></div>
 ${phases.map(p=>`<section class="phase"><div class="phase-num">${String(p.id).padStart(2,'0')}</div><div><h3>${esc(p.title)}</h3><p>${esc(p.goal)}</p>${lessons.filter(l=>l.phase===p.id).map(l=>`<a class="lesson-row ${isDone('lesson/'+l.id)?'completed':''}" href="#lesson/${l.id}"><strong>${esc(l.title)}</strong><span>${isDone('lesson/'+l.id)?'✓ Complete':'Learn →'}</span></a>`).join('')}</div></section>`).join('')}
 <div class="section-heading"><h2>Choose your pace</h2><span>Suggested schedules, not readiness guarantees</span></div><div class="plan"><div><h3>4 weeks · focused review</h3><p>For experienced engineers. Week 1: phases 1–4. Week 2: phases 5–7. Week 3: phases 8–10 and one design daily. Week 4: unseen timed designs and targeted revision.</p></div><div><h3>8 weeks · balanced</h3><p>Weeks 1–3: phases 1–6. Weeks 4–5: phases 7–10. Weeks 6–7: compare two designs per session. Week 8: timed mocks and repair the gaps revealed by follow-ups.</p></div><div><h3>12 weeks · from scratch</h3><p>One phase per week for ten weeks. Pair each phase with a related design and a small experiment. Use the final two weeks for unfamiliar designs, failure drills and explanation practice.</p></div></div>
 <details><summary>Build three small systems to test your understanding</summary><ol><li><strong>URL service:</strong> create and redirect links, add a bounded cache, measure hot-key traffic and cold-cache behavior. Deliver a latency chart and a deletion test.</li><li><strong>Reliable worker:</strong> commit a business row and outbox event together. Crash after publishing and before acknowledging. Demonstrate one intended effect after replay.</li><li><strong>Reservation service:</strong> race concurrent requests for the last unit. Add hold expiry, payment-pending state and late-success reconciliation. Show that confirmed ownership remains unique.</li></ol><p class="small">These are implementation exercises to run in your own environment; the browser does not execute a backend lab.</p></details>
 <p class="small">Focus: high-level system design and distributed systems. Low-level object design and coding are separate skills. The examples use stated assumptions and are not claims about any company’s internal architecture. Inspired by the phased, practical learning approach of <a href="https://github.com/rohitg00/ai-engineering-from-scratch" target="_blank" rel="noopener noreferrer">AI Engineering from Scratch ↗</a>.</p>`;}
function calculator(){return `<div class="calculator"><h3>Work the numbers</h3><p class="small">Decimal KB and GB. Storage includes the chosen replicas; indexes and compression are excluded.</p><div class="fields">${[['users','Daily active users',10000000],['reads','Reads per user / day',20],['writes','Writes per user / day',2],['peak','Peak multiplier',5],['bytes','Record size (KB)',1],['days','Retention (days)',30],['replicas','Storage copies',3]].map(([id,label,val])=>`<label>${label}<input id="calc-${id}" data-calc type="number" min="${['peak','replicas'].includes(id)?1:0}" step="any" value="${val}"></label>`).join('')}</div><div id="calc-results" class="calc-results" aria-live="polite"></div></div>`;}
function estimate(v){const avg=v.users*v.reads/86400,writes=v.users*v.writes/86400;return {avg,peak:avg*v.peak,writes,gb:v.users*v.writes*v.bytes*1000*v.days*v.replicas/1e9};}
function updateCalculator(){const ids=['users','reads','writes','peak','bytes','days','replicas'];const values=Object.fromEntries(ids.map(id=>[id,Number($('#calc-'+id).value)]));if(ids.some(id=>$('#calc-'+id).value.trim()===''||!Number.isFinite(values[id])||values[id]<(['peak','replicas'].includes(id)?1:0))){$('#calc-results').textContent='Enter valid nonnegative values; peak multiplier and copies must be at least one.';return;}const r=estimate(values);if(Object.values(r).some(v=>!Number.isFinite(v))){$('#calc-results').textContent='These values are too large to calculate.';return;}const fmt=v=>v.toLocaleString(undefined,{maximumFractionDigits:2});$('#calc-results').innerHTML=[[r.avg,'average reads / second'],[r.peak,'peak reads / second'],[r.writes,'average writes / second'],[r.gb,'GB retained with copies']].map(([n,label])=>`<div><strong>${fmt(n)}</strong><span>${label}</span></div>`).join('');}
function rubric(){return `<details><summary>Score an unseen design</summary><p class="small">0 = missing or incorrect · 1 = plausible with gaps · 2 = clear, justified and tested against failure. Self-assessment only; no automatic evaluation.</p><div class="rubric">${['Requirements','Capacity reasoning','Data and API','Correctness','Tradeoffs','Operations'].map((label,i)=>`<label>${label}<select data-score aria-label="${label} score"><option value="">Choose evidence level</option><option value="0">0 · Missing</option><option value="1">1 · Partial</option><option value="2">2 · Defensible</option></select></label>`).join('')}</div><p id="score-result" class="small" aria-live="polite">Score all six areas after your attempt.</p></details>`;}
function lesson(id){const l=lessons.find(x=>x.id===id);if(!l)return missing();const related=patterns.filter(p=>p.lesson===id);return `<div class="reader-layout"><article class="reader">${head('Phase '+String(l.phase).padStart(2,'0')+' · '+phases[l.phase-1].title,l.title,'Read, work the example, then explain the answer in your own words.')}<div class="actions">${doneButton('lesson',id)}</div>${section('theory','The idea',l.model)}${section('example','Worked example',l.worked)}${id==='estimation'?calculator():''}${section('tradeoffs','Tradeoffs and common mistakes',l.tradeoff)}<section id="exercise"><h2>Try it yourself</h2><p>${esc(l.exercise)}</p><details><summary>Reveal the reasoning</summary><p>${esc(l.answer)}</p></details></section>${id==='mastery'?rubric():''}${related.length?`<h2>Patterns that use this lesson</h2><div class="chips">${related.map(p=>`<a href="#pattern/${p.id}">${esc(p.title)} →</a>`).join('')}</div>`:''}${references(l.refs)}${navPair(lessons,l,'lesson')}</article>${toc([['theory','The idea'],['example','Worked example'],['tradeoffs','Tradeoffs'],['exercise','Exercise']],'<hr><a href="#learn">← Learning path</a>')}</div>`;}
function catalog(kind){const pats=kind==='patterns';const list=pats?patterns:designs;const categories=pats?[...new Set(patterns.map(p=>p.category))]:['Foundation','Intermediate','Advanced'];return head(pats?'Recognize the constraint':'Practice the conversation',pats?'A pattern is a decision.':'Design it. Then break it.',pats?'Learn when a pattern helps, how it works, where it fails and when to avoid it. Each pattern connects to its underlying theory and worked designs.':'Try a prompt before reading its blueprint. Every design includes requirements, capacity assumptions, APIs, data, request flows, failure handling and follow-ups.')+`<div class="toolbar"><input id="search" type="search" aria-label="Search ${pats?'patterns':'design questions'}" placeholder="${pats?'Search patterns, constraints, failure modes…':'Search systems, requirements, tradeoffs…'}"><select id="filter" aria-label="${pats?'Pattern category':'Difficulty'}"><option value="">${pats?'All categories':'All levels'}</option>${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="completion" aria-label="Completion status"><option value="">All progress</option><option value="todo">Not completed</option><option value="done">Completed</option></select></div><p class="result-count" id="result-count" aria-live="polite"></p><div class="cards" id="results"></div>`;}
function filterItems(kind,query='',category='',status=''){const pats=kind==='patterns',type=pats?'pattern':'design';return (pats?patterns:designs).filter(x=>(!category||(pats?x.category:x.level)===category)&&(!query||JSON.stringify(x).toLowerCase().includes(query.toLowerCase()))&&(!status||(status==='done')===isDone(type+'/'+x.id)));}
function updateResults(kind){const pats=kind==='patterns',type=pats?'pattern':'design',list=filterItems(kind,$('#search').value,$('#filter').value,$('#completion').value);$('#result-count').textContent=`${list.length} ${pats?'patterns':'design questions'}`;$('#results').innerHTML=list.length?list.map(x=>`<a class="card" href="#${type}/${x.id}"><div class="meta"><span>${esc(pats?x.category:x.level)}</span><span>${isDone(type+'/'+x.id)?'✓ Completed':''}</span></div><h3>${esc(x.title)}</h3><p>${esc(pats?x.signal:x.requirements)}</p><span class="arrow">${pats?'Understand the pattern':'Work through the design'} →</span></a>`).join(''):'<p class="empty">No matches. Try another search or clear the filters.</p>';}
function pattern(id){const p=patterns.find(x=>x.id===id);if(!p)return missing();const related=designs.filter(d=>d.patterns.includes(id));return `<div class="reader-layout"><article class="reader">${head(p.category,p.title,p.signal)}<div class="actions">${doneButton('pattern',id)}<a class="button secondary" href="#lesson/${p.lesson}">Read the underlying theory →</a></div>${section('mechanism','How it works',p.mechanism)}${section('failure','What breaks',p.failure)}${section('boundary','When to avoid it',p.avoid)}<div class="callout"><strong>Explain it without a diagram</strong><p>What is the source of truth? Where is the acknowledgment point? What happens if a process crashes immediately before or after it? Name one alternative and explain why you rejected it.</p></div><h2>Apply it to a design</h2><div class="chips">${related.length?related.map(d=>`<a href="#design/${d.id}">${esc(d.title)} →</a>`).join(''):`<a href="#questions">Choose a design and justify this pattern →</a>`}</div>${references(p.refs)}${navPair(patterns,p,'pattern')}</article>${toc([['mechanism','How it works'],['failure','Failure mode'],['boundary','When to avoid']],'<hr><a href="#patterns">← All patterns</a>')}</div>`;}
function design(id){const d=designs.find(x=>x.id===id);if(!d)return missing();return `<div class="reader-layout"><article class="reader">${head(d.level+' · worked design',d.title,d.requirements)}<div class="actions">${doneButton('design',id)}</div><div class="timer-box"><output id="timer" aria-label="Time remaining">45:00</output><button id="timer-start" class="button secondary">Start 45-minute attempt</button><button id="timer-reset" class="button secondary">Reset</button><span class="small">0–5 requirements · 5–10 sizing/API · 10–20 architecture · 20–35 deep dives · 35–42 failure/operations · 42–45 recap</span></div><div class="callout"><strong>Before you reveal the blueprint</strong><p>Write your assumptions, draw one read and write path, identify the hardest invariant and choose two deep dives. The blueprint is one defensible starting point, not a single correct answer.</p></div><details id="blueprint"><summary>Reveal the worked design</summary>${section('sizing','1. Capacity assumptions',d.scale)}${section('api','2. API contract',d.api)}${section('data','3. Data model',d.data)}<section id="flow"><h2>4. Request and data flows</h2><ol class="flow">${d.flow.map((s,i)=>`<li><b>${String(i+1).padStart(2,'0')}</b><span>${esc(s)}</span></li>`).join('')}</ol></section>${section('decision','5. The decision to defend',d.decision)}${section('failure','6. Failure and recovery',d.failure)}<h2>Patterns in this design</h2><div class="chips">${d.patterns.map(id=>`<a href="#pattern/${id}">${esc(patterns.find(p=>p.id===id).title)} →</a>`).join('')}</div>${references(d.patterns.flatMap(id=>patterns.find(p=>p.id===id).refs))}</details><section id="followups"><h2>Change the constraints</h2><ol>${d.followup.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></section><details><summary>Operational checklist for this design</summary><ul><li>Define user-visible success and latency targets; instrument both request acceptance and completion.</li><li>Name a hot key, a failed dependency and a region outage. State which operations continue.</li><li>Set the durability acknowledgment, recovery point and recovery time objectives.</li><li>Explain tenant isolation, authorization, sensitive-data retention and deletion propagation.</li><li>Estimate the dominant cost; describe a compatible migration and a rollback limit.</li></ul></details>${rubric()}${navPair(designs,d,'design')}</article>${toc([['blueprint','Worked blueprint'],['followups','Follow-up questions']],'<hr><a href="#questions">← All designs</a>')}</div>`;}
function missing(){return head('Page not found','This page is not in the guide.','Choose a lesson, pattern or design question from the navigation.')+'<a class="button" href="#learn">Return to Learn</a>';}
function tick(){if(timerEnd!==null)timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));const out=$('#timer');if(out)out.textContent=`${String(Math.floor(timerRemaining/60)).padStart(2,'0')}:${String(timerRemaining%60).padStart(2,'0')}`;if(timerRemaining===0&&timerEnd!==null){clearInterval(timerInterval);timerEnd=null;$('#timer-start').textContent='Attempt finished';$('#timer-start').disabled=true;notify('Time is up. Recap your tradeoffs and score the design.');}}
function bindTimer(id){if(timerDesign!==id){timerRemaining=2700;timerDesign=id;}tick();$('#timer-start').textContent=timerEnd?'Pause':timerRemaining===2700?'Start 45-minute attempt':'Resume';$('#timer-start').disabled=timerRemaining===0;$('#timer-start').onclick=()=>{if(timerEnd){tick();timerEnd=null;clearInterval(timerInterval);$('#timer-start').textContent='Resume';}else{timerEnd=Date.now()+timerRemaining*1000;timerInterval=setInterval(tick,250);$('#timer-start').textContent='Pause';tick();}};$('#timer-reset').onclick=()=>{clearInterval(timerInterval);timerEnd=null;timerRemaining=2700;$('#timer-start').disabled=false;$('#timer-start').textContent='Start 45-minute attempt';tick();};}
function bindScores(){document.querySelectorAll('[data-score]').forEach(s=>s.onchange=()=>{const v=[...document.querySelectorAll('[data-score]')].map(x=>x.value);if(v.some(x=>x==='')){$('#score-result').textContent='Score all six areas after your attempt.';return;}const sum=v.reduce((a,b)=>a+Number(b),0);$('#score-result').textContent=`${sum}/12. ${v.includes('0')?'Revisit every area scored zero before your next mock.':'Now test transfer with a different prompt and a changed constraint.'}`;});}
function render(){const route=location.hash.replace(/^#/,'')||'learn';const [page,id]=route.split('/');if(timerEnd!==null){timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerEnd=null;}clearInterval(timerInterval);const active=page==='lesson'?'learn':page==='pattern'?'patterns':page==='design'?'questions':page;document.querySelectorAll('[data-nav]').forEach(a=>{const on=a.dataset.nav===active;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const title=page==='lesson'?lessons.find(x=>x.id===id)?.title:page==='pattern'?patterns.find(x=>x.id===id)?.title:page==='design'?designs.find(x=>x.id===id)?.title:({learn:'Learning path',patterns:'Pattern catalog',questions:'Design questions'})[page];$('#breadcrumb').textContent=title||'Page not found';document.title=(title?title+' · ':'')+'System Design Path';$('#view').innerHTML=page==='learn'?learn():page==='lesson'?lesson(id):page==='patterns'||page==='questions'?catalog(page):page==='pattern'?pattern(id):page==='design'?design(id):missing();updateProgress();document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{const value=b.dataset.complete;if(isDone(value))saved.done=saved.done.filter(x=>x!==value);else saved.done.push(value);persist();const done=isDone(value);b.classList.toggle('done',done);b.classList.toggle('secondary',!done);b.setAttribute('aria-pressed',String(done));b.textContent=done?'✓ Completed':'Mark complete';updateProgress();});document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();const target=document.getElementById(a.dataset.scroll);if(target){if(target.tagName==='DETAILS')target.open=true;target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}});if(page==='patterns'||page==='questions'){['search','filter','completion'].forEach(x=>$('#'+x).addEventListener(x==='search'?'input':'change',()=>updateResults(page)));updateResults(page);}if($('#calc-results')){document.querySelectorAll('[data-calc]').forEach(x=>x.addEventListener('input',updateCalculator));updateCalculator();}if($('#timer'))bindTimer(id);bindScores();}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#view').focus({preventScroll:true});});
window.addEventListener('storage',e=>{if(e.key===key){try{const value=JSON.parse(e.newValue||'{"done":[]}');if(Array.isArray(value.done)){saved.done=value.done.filter(x=>validKeys.has(x));render();}}catch{}}});
render();
